effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   /////////////////////////

    const float PI = 3.1415;

    // const float CamSpeed = 1.0;
    // const vec3 CubeColor = vec3(0.99, 0.1, 0.05) * 0.9;
    const vec3 BackgroundColor = vec3(0.0, 0.0, 0.0);
    // const float CubeFatness = 0.2;
    // const float CubeDist = 3.0;
    // const float RotationFactor = 0.1;

    float map(vec3 p);

    vec3 approxNormal(vec3 pos)
    {
        float epsilon = 0.001;
    	vec2 t = vec2(0.0, epsilon);
        vec3 n = vec3(map(pos + t.yxx) - map(pos - t.yxx),
               	  map(pos + t.xyx) - map(pos - t.xyx),
                  map(pos + t.xxy) - map(pos - t.xxy));
        return normalize(n);
    }

    float sdBox(vec3 p, vec3 boxDims)
    {
      vec3 d = abs(p) - boxDims;
      return min(max(d.x,max(d.y,d.z)),0.0) +
             length(max(d,0.0));
    }

    float map(vec3 p)
    {
        float d = 99999.0;

        float c = cos(progressb * p.z);
        float s = sin(progressb * p.z);
        mat2 m = mat2(c, -s, s, c);
        p = vec3(m * p.xy, p.z);

        p = mod(p, progresse) - 0.5 * progresse;
        d = min(d, sdBox(p, vec3(0.5 * progresse, progressd, progressd)));
        d = min(d, sdBox(p, vec3(progressd, 0.5 * progresse, progressd)));
        d = min(d, sdBox(p, vec3(progressd, progressd, 0.5 * progresse)));

        return d;
    }

    vec3 getColor(vec3 rayPos, vec3 rayDir)
    {
        vec3 color = BackgroundColor;

        float total_dist = 0.0;
        float d;
        int iters = 0;
        for (int i = 0; i < 128; ++i)
        {
        	++iters;
        	d = map(rayPos);
            rayPos += d * rayDir;
            total_dist += d;
            if (d < 0.0001)
            {
            	break;
            }
        }

        if (d < 0.001)
        {
        	float iter_factor = float(iters) / 128.0;
        	//////////////////////////
        	color = (vec3(1.-(vec3(colorx.rgb)+vec3(0.28,0.28,0.28))*0.9)) * vec3(1.-iter_factor);
        	// color = (vec3(1.-colorx.rgb)*0.9) * vec3(1.-iter_factor);

        	float bg_mix_factor = max(0.0, total_dist / 100.0);
        	color = mix(color, BackgroundColor, bg_mix_factor);
            color = vec3(1.0) - color * 18.0;
        }

        return color;
    }

    vec3 camRail(float t)
    {
    	return vec3(0.0, 0.0, t);
    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        if (adaptive) { TanRyu = acScreenNorm; }
        else { 
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;
        }

        TanRyu /= scale;
        TanRyu *= rot2m(angle*0.0174533);
        TanRyu += position*vec2(-1.,1.)/500.;

        /////////////////////////

    	vec4 result;

    	vec2 uv = TanRyu;
        float aspect = acScreenSize.x / acScreenSize.y;
        // float aspect = TanRyu.x / TanRyu.y;

        // Make uv go [-0.5, 0.5] and scale uv.x according to aspect ratio
        uv -= .5;
        uv.x = aspect * uv.x;

        // Initialize camera stuff
        vec3 camPos = camRail(1.0 * 50.0);
        vec3 camTarget = camRail(1.0 * 1.0 + 0.1);
        vec3 camUp = vec3(0., 1., 0.);
        vec3 camDir = normalize(camTarget - camPos);
        vec3 camRight = normalize(cross(camUp, camDir));
        camUp = normalize(cross(camDir, camRight));

        vec3 rayPos = camPos;
        vec3 rayDir = normalize(camDir + uv.x * camRight + uv.y * camUp);

        // Raymarch scene to get pixel color
        vec3 color = getColor(rayPos, rayDir);

        // Set pixel color
    	result = vec4(color, 1.0);

    	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            vec4 gradmap;
            float luminance = dot(result.rgb, luminanceWeighting);
            gradmap = mix(color1,color2,luminance)*result.a;

    	// vec4 factor = mix(texColorX,gradmap,alpha);
    	vec4 factor = mix(texColorX,result,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
